import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../state/app_state.dart';

class AddressesScreen extends StatefulWidget { const AddressesScreen({super.key}); @override State<AddressesScreen> createState() => _AddressesScreenState(); }
class _AddressesScreenState extends State<AddressesScreen> {
  late Future<dynamic> future;
  @override void initState() { super.initState(); future = context.read<AppState>().api.get('addresses'); }
  @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Adreslerim'), actions: [IconButton(onPressed: _add, icon: const Icon(Icons.add))]), body: FutureBuilder<dynamic>(future: future, builder: (_, snapshot) { if (snapshot.connectionState != ConnectionState.done) return const Center(child: CircularProgressIndicator()); if (snapshot.hasError) return Center(child: Text('${snapshot.error}')); final payload = snapshot.data is Map ? snapshot.data as Map : const {}; final rows = ((payload['data'] as List?) ?? const []).whereType<Map>().toList(); if (rows.isEmpty) return Center(child: FilledButton(onPressed: _add, child: const Text('İlk adresi ekle'))); return ListView.separated(padding: const EdgeInsets.all(16), itemCount: rows.length, separatorBuilder: (_, __) => const SizedBox(height: 10), itemBuilder: (_, i) { final address = rows[i]; return Card(child: ListTile(title: Text('${address['label'] ?? 'Adres'}${address['is_default'] == 1 ? ' · Varsayılan' : ''}'), subtitle: Text('${address['full_name'] ?? ''}\n${address['city'] ?? ''} / ${address['district'] ?? ''}\n${address['address_text'] ?? ''}'), isThreeLine: true, trailing: IconButton(onPressed: () async { await context.read<AppState>().api.delete('addresses/${address['id_address']}', body: {}); setState(() => future = context.read<AppState>().api.get('addresses')); }, icon: const Icon(Icons.delete_outline)))); }); }));
  Future<void> _add() async { final name = TextEditingController(), phone = TextEditingController(), city = TextEditingController(), district = TextEditingController(), text = TextEditingController(), label = TextEditingController(); final form = GlobalKey<FormState>(); final saved = await showDialog<bool>(context: context, builder: (_) => AlertDialog(title: const Text('Yeni adres'), content: Form(key: form, child: SingleChildScrollView(child: Column(children: [TextFormField(controller: label, decoration: const InputDecoration(labelText: 'Adres başlığı')), TextFormField(controller: name, decoration: const InputDecoration(labelText: 'Ad soyad'), validator: (v) => v!.isEmpty ? 'Zorunlu' : null), TextFormField(controller: phone, decoration: const InputDecoration(labelText: 'Telefon'), validator: (v) => v!.isEmpty ? 'Zorunlu' : null), TextFormField(controller: city, decoration: const InputDecoration(labelText: 'İl'), validator: (v) => v!.isEmpty ? 'Zorunlu' : null), TextFormField(controller: district, decoration: const InputDecoration(labelText: 'İlçe'), validator: (v) => v!.isEmpty ? 'Zorunlu' : null), TextFormField(controller: text, maxLines: 3, decoration: const InputDecoration(labelText: 'Açık adres'), validator: (v) => v!.isEmpty ? 'Zorunlu' : null)]))), actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Vazgeç')), FilledButton(onPressed: () async { if (!form.currentState!.validate()) return; await context.read<AppState>().api.post('addresses', body: {'label': label.text, 'full_name': name.text, 'phone': phone.text, 'city': city.text, 'district': district.text, 'address_text': text.text, 'is_default': 1}); if (context.mounted) Navigator.pop(context, true); }, child: const Text('Kaydet'))])); if (saved == true && mounted) setState(() => future = context.read<AppState>().api.get('addresses')); }
}
